{"command": "cat > /tmp/sse-timing.mjs <<'EOF'
import http from 'node:http'

const HOST = '172.18.0.8'
const PORT = 18990

function fetchStream(path) {
  return new Promise((resolve, reject) => {
    const started = Date.now()
    const chunks = []
    let buffer = ''
    const req = http.get({ host: HOST, port: PORT, path, headers: { Accept: 'text/event-stream', Connection: 'close' } }, (res) => {
      if (res.statusCode !== 200) {
        res.resume()
        reject(new Error(`HTTP ${res.statusCode} for ${path}`))
        return
      }
      res.setEncoding('utf8')
      res.on('data', (chunk) => {
        const now = Date.now() - started
        for (const line of chunk.split('\n')) {
          if (line.startsWith('data:')) chunks.push({ at: now, line: line.trim() })
        }
      })
      res.on('end', () => resolve({ path, chunks, total: Date.now() - started }))
    })
    req.setTimeout(15000, () => { req.destroy(); reject(new Error('timeout')) })
    req.on('error', reject)
  })
}

for (const path of ['/sse', '/sse-buffered']) {
  try {
    const r = await fetchStream(path)
    console.log(`\n=== ${path} (total ${r.total}ms) ===`)
    for (const c of r.chunks) console.log(`  +${c.at}ms  ${c.line}`)
  } catch (e) {
    console.log(`\n=== ${path} FAILED: ${e.message}`)
  }
}
EOF
node /tmp/sse-timing.mjs 2>&1", "description": "用 Node 客户端逐帧计时对比缓冲行为", "timeoutMs": 60000}

