/// <reference types="vite/client" />
=== client interceptors ===
/** SSE 收到 401 且刷新失败时，通知外壳回到登录页。 */
export function notifyUnauthorized(): void {
  unauthorizedHandler?.()
}

export function createHttpClient(options: HttpClientOptions = {}): AxiosInstance {
  const client = axios.create({
    baseURL: options.baseURL ?? resolveBaseUrl(),
    timeout: 30_000,
    headers: { Accept: 'application/json' },
  })

  const refresh = options.refresh ?? refreshSession
  let refreshPromise: Promise<AuthTokens> | null = null

  async function refreshOnce(): Promise<AuthTokens> {
    if (!refreshPromise) {
      refreshPromise = refresh().finally(() => {
        refreshPromise = null
      })
    }
    return refreshPromise
  }

  function handleUnauthorized(): void {
    storage.clearTokens()
    options.onUnauthorized?.()
    if (!options.onUnauthorized) {
      unauthorizedHandler?.()
    }
  }

  client.interceptors.request.use((config) => {
    const token = storage.getAccessToken()
    if (token) {
      config.headers.set('Authorization', `Bearer ${token}`)
    }
    return config
  })

  client.interceptors.response.use(
    (response) => response,
    async (error: unknown) => {
      if (!isUnauthorized(error)) {
        throw toApiRequestError(error)
      }

      const config = error.config as RetryableConfig | undefined
      const isRefreshRequest = config?.url?.includes('/auth/refresh')

      if (!config || config._retry || isRefreshRequest) {
        handleUnauthorized()
        throw toApiRequestError(error)
      }

      config._retry = true
      try {
        await refreshOnce()
        return await client.request(config)
      } catch {
        handleUnauthorized()
        throw new ApiRequestError('登录已过期，请重新登录', {
          code: 'unauthorized',
          status: 401,
        })
      }
    },
  )

  return client
}

export const apiClient = createHttpClient()

import { AxiosError, type AxiosResponse, type InternalAxiosRequestConfig } from 'axios'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { ApiRequestError, createHttpClient } from '@/api/client'
