import {
  getBuildInfo,
  getRecentErrors,
  getRecentRequests,
  getRuntimeContext,
  recordError,
  recordRequest,
  resetDiagnostics,
  setRuntimeContext,
} from '@/utils/diagnostics'

const req = (i: number) => ({
  method: 'GET',
  url: `/x/${i}`,
  status: 200,
  durationMs: 5,
  requestId: `req-${i}`,
  traceId: '',
  at: i,
})

describe('diagnostics', () => {
  beforeEach(() => resetDiagnostics())

  it('环形缓冲只保留最近 20 条且新在前', () => {
    for (let i = 1; i <= 25; i += 1) recordRequest(req(i))
    const rows = getRecentRequests()
