确认失败（模块不存在）。现在实现。

创建 `src/utils/diagnostics.ts`。

设计：
```ts
export interface RequestRecord { method: string; url: string; status: number; durationMs: number; requestId: string; traceId: string; at: number }
export interface ErrorRecord { code: string; message: string; requestId: string; at: number }
export interface BuildInfo { version: string; buildTime: string; gitSha: string; apiBase: string; mock: boolean }

const CAPACITY = 20
const requests: RequestRecord[] = []
const errors: ErrorRecord[] = []
let runtime: { runId: string | null; conversationId: string | null } = { runId: null, conversationId: null }

function push<T>(list: T[], item: T): void {
  list.unshift(item)
  if (list.length > CAPACITY) list.length = CAPACITY
}

export function recordRequest(record: RequestRecord): void { push(requests, record) }
export function recordError(record: ErrorRecord): void { push(errors, record) }
export function getRecentRequests(limit = CAPACITY): RequestRecord[] { return requests.slice(0, limit) }
export function getRecentErrors(limit = CAPACITY): ErrorRecord[] { return errors.slice(0, limit) }

export function getBuildInfo(): BuildInfo {
  return {
    version: typeof __APP_VERSION__ === 'string' ? __APP_VERSION__ : 'dev',
    buildTime: typeof __BUILD_TIME__ === 'string' ? __BUILD_TIME__ : '',
    gitSha: typeof __GIT_SHA__ === 'string' ? __GIT_SHA__ : 'unknown',
    apiBase: import.meta.env.VITE_API_BASE_URL?.trim() || '/api/v1',
    mock: import.meta.env.VITE_USE_MOCK === 'true',
  }
}
export function setRuntimeContext(ctx: { runId?: string | null; conversationId?: string | null }): void {
  runtime = {
    runId: ctx.runId === undefined ? runtime.runId : ctx.runId,
    conversationId: ctx.conversationId === undefined ? runtime.conversationId : ctx.conversationId,
  }
}
export function getRuntimeContext() { return { ...runtime } }
export function resetDiagnostics(): void { requests.length = 0; errors.length = 0; runtime = { runId: null, conversationId: null } }
```

注意 `typeof __APP_VERSION__ === 'string'` 在 vitest 中全局未定义会有 ReferenceError？`typeof undeclaredVar` 不抛错（安全）。但 define 会把源码里的 `__APP_VERSION__` 替换为字符串字面量；vitest 没定义时 `typeof __APP_VERSION__` 返回 'undefined'。OK。

不过 vitest 的 `define` 配置在 vitest.config.ts 里没有，`import.meta.env.VITE_API_BASE_URL` 可用。

`typeof __APP_VERSION__ === 'string' ? __APP_VERSION__ : 'dev'` —— 当未定义时，第二个分支不会执行（短路），安全。

然后 vite.config.ts 加 define。

vite.config.ts 当前：
```ts
import { fileURLToPath, URL } from 'node:url'
import { defineConfig } from 'vite'
...
export default defineConfig({ ... })
```

改为：
```ts
import { execSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { fileURLToPath, URL } from 'node:url'
...
const pkg = JSON.parse(readFileSync(new URL('./package.json', import.meta.url), 'utf8')) as { version: string }
const gitSha = (() => { try { return execSync('git rev-parse --short HEAD', { stdio: ['ignore','pipe','ignore'] }).toString().trim() } catch { return 'unknown' } })()

export default defineConfig({
  define: {
    __APP_VERSION__: JSON.stringify(pkg.version),
    __BUILD_TIME__: JSON.stringify(new Date().toISOString()),
    __GIT_SHA__: JSON.stringify(gitSha),
  },
  ...
})
```

注意：`new Date().toISOString()` 在配置加载时求值一次。

env.d.ts 加 declare。

client.ts 修改：
- request 拦截器记录 startedAt（config.metadata）。axios 的 InternalAxiosRequestConfig 有 metadata 字段（v1 支持 `config.metadata` 吗？axios 有 `metadata` 自定义字段，类型上允许任意扩展）。用 `(config as any).metadata = { startedAt: performance.now() }` 或定义扩展类型。

  简单：用 WeakMap<InternalAxiosRequestConfig, number> 记录开始时间，避免类型扩展。

- 响应成功拦截器：
```ts
(response) => {
  recordRequest({
    method: (response.config.method ?? 'get').toUpperCase(),
    url: response.config.url ?? '',
    status: response.status,
    durationMs: elapsed(response.config),
    requestId: readHeader(response.headers, 'x-request-id'),
    traceId: readHeader(response.headers, 'x-trace-id'),
    at: Date.now(),
  })
  return response
