  if (props.connection === 'reconnecting') {
    if (!online.value) return '网络已断开，恢复后自动重连'
    return `连接中断，正在重新连接（第 ${props.attempt}/${props.maxAttempts} 次）`
  }
  return '连接已断开，正在通过轮询恢复'
})
</script>

