# Agent Hub Web 生产环境 Nginx 配置（完整 nginx.conf）
#
# 用法：
#   1. 备份原 /etc/nginx/nginx.conf；
#   2. 按实际环境修改 upstream 地址与 root；
#   3. 用本文件替换 /etc/nginx/nginx.conf；
#   4. nginx -t && nginx -s reload。
#
# 注意：本文件是完整配置（含 events/http/server），不是 conf.d 片段。
# 若部署环境只允许投放 conf.d 片段，请把 server { ... } 拆出，并确保
# 主配置的 http 块内存在同名 upstream agent-hub-backend。

worker_processes auto;
pid /var/run/nginx.pid;
error_log /var/log/nginx/error.log warn;

events {
    worker_connections 1024;
    multi_accept on;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for" '
                    'rt=$request_time urt=$upstream_response_time';
    access_log /var/log/nginx/access.log main;

    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
    server_tokens off;

    # 普通文本资源启用压缩；SSE 的 location 内单独 gzip off。
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types
        text/plain
        text/css
        text/javascript
        application/javascript
        application/json
        application/xml
        image/svg+xml;

    # 后端地址：容器编排中可改为服务名（如 agent-hub-backend:8000）。
    # keepalive 复用少量后端连接，降低普通 JSON 请求的握手开销。
    upstream agent-hub-backend {
        server 127.0.0.1:8000;
        keepalive 32;
    }

    server {
        listen 80;
        server_name _;

        root /usr/share/nginx/html;
        index index.html;

        # SPA fallback：真实文件优先；刷新前端路由时回落到 index.html。
        location / {
            try_files $uri $uri/ /index.html;
        }

        # 带内容哈希的构建产物：一年强缓存 + immutable，减少重复下载。
        # 文件名随内容变化，因此可以安全地使用长缓存。

 * 调度下一次自动重连：1s/2s/4s/8s/16s ±20%，最多 5 次、总窗口 60s。
 * 定时器到点只执行一次「GET run 校验 + 重发流」，失败会回到这里累计次数。
 */
function scheduleReconnect(): void {
  if (!lastAttempt.value || !state.value.runId) return
  if (state.value.finishReason !== null || isTerminal(state.value.runStatus)) return
  if (connection.value === 'degraded') return
  // onerror 与 onclose 可能先后到达；已有定时器时只保留一次调度。
  // 不能把「本次请求在途」也算作重复：catch 里正是请求失败后在排队下一次。
  if (connection.value === 'reconnecting' && reconnectTimer !== null) return

  connection.value = 'reconnecting'
  state.value = { ...state.value, streaming: true, error: null, recovery: null }
  bindConnectivityListeners()

  // 离线：暂停计时、不消耗次数；online 事件会立即重试。
  if (typeof navigator !== 'undefined' && navigator.onLine === false) {
    clearReconnectTimer()
    return
  }

  if (reconnectAttempt.value >= MAX_RECONNECT_ATTEMPTS) {
    enterDegraded('连接中断，自动重连已达上限，改为轮询恢复。')
    return
  }

  const now = Date.now()
  if (reconnectWindowStartedAt === null) reconnectWindowStartedAt = now
  const delay = nextReconnectDelay(reconnectAttempt.value)
  if (now - reconnectWindowStartedAt + delay > RECONNECT_WINDOW_MS) {
    enterDegraded('连接中断，重连总时长已超过 60 秒，改为轮询恢复。')
    return
  }

  reconnectAttempt.value += 1
  clearReconnectTimer()
  reconnectTimer = setTimeout(() => {
    reconnectTimer = null
    void performReconnect()
  }, delay)
}

