    await expect(panel.getByText('退款政策').first()).toBeVisible({ timeout: 15_000 })
  })

  test('检索无命中时给出空态提示', async ({ page }) => {
    await login(page)
    await page.getByRole('link', { name: '知识库' }).click()

    const panel = page.getByRole('region', { name: '检索调试' })
