    await panel.getByTestId('debug-query').fill('不存在的检索词-xyz')
    await panel.getByRole('button', { name: '检索', exact: true }).click()

    await expect(panel.getByText('没有命中片段')).toBeVisible({ timeout: 15_000 })
  })
})
